	"Validation": [
		{ name: "Add", kind: "method", signature: "Add(Type As XlDVType, [AlertStyle As Variant], [Operator As Variant], [Formula1 As Variant], [Formula2 As Variant])", doc: {"summary":"Adds data validation to the specified range.","params":[{"name":"Type","text":"The validation type.","type":"XlDVType"},{"name":"AlertStyle","text":"The validation alert style. Can be one of the following XlDVAlertStyle constants: xlValidAlertInformation, xlValidAlertStop, or xlValidAlertWarning.","type":"Variant"},{"name":"Operator","text":"The data validation operator. Can be one of the following XlFormatConditionOperator constants: xlBetween, xlEqual, xlGreater, xlGreaterEqual, xlLess, xlLessEqual, xlNotBetween, or xlNotEqual.","type":"Variant"},{"name":"Formula1","text":"The first part of the data validation equation. Value must not exceed 255 characters.","type":"Variant"},{"name":"Formula2","text":"The second part of the data validation equation when _Operator_ is xlBetween or xlNotBetween (otherwise, this argument is ignored).","type":"Variant"}],"source":"external"} },
		{ name: "AlertStyle", kind: "property", declaredType: "Long", access: "read-only", doc: {"summary":"Returns the validation alert style. Read-only XlDVAlertStyle.","params":[],"source":"external"} },
		{ name: "Application", kind: "property", returns: "Excel.Application", declaredType: "Application", access: "read-only", doc: {"summary":"When used without an object qualifier, this property returns an Application object that represents the Microsoft Excel application.","params":[],"source":"external"} },
		{ name: "Creator", kind: "property", declaredType: "XlCreator", access: "read-only", doc: {"summary":"Returns a 32-bit integer that indicates the application in which this object was created. Read-only Long.","params":[],"source":"external"} },
		{ name: "Delete", kind: "method", signature: "Delete()", doc: {"summary":"Deletes the object.","params":[],"source":"external"} },
		{ name: "ErrorMessage", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Returns or sets the data validation error message. Read/write String.","params":[],"source":"external"} },
		{ name: "ErrorTitle", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Returns or sets the title of the data-validation error dialog box. Read/write String.","params":[],"source":"external"} },
		{ name: "Formula1", kind: "property", declaredType: "String", access: "read-only", doc: {"summary":"Returns the value or expression associated with the conditional format or data validation. Can be a constant value, a string value, a cell reference, or a formula. Read-only String.","params":[],"source":"external"} },
		{ name: "Formula2", kind: "property", declaredType: "String", access: "read-only", doc: {"summary":"Returns the value or expression associated with the second part of a conditional format or data validation. Used only when the data validation conditional format Operator property is xlBetween or xlNotBetween (XlFormatConditionOperator). Can be a constant value, a string value, a cell reference, or a formula. Read-only String.","params":[],"source":"external"} },
		{ name: "IgnoreBlank", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if blank values are permitted by the range data validation. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "IMEMode", kind: "property", declaredType: "Long", access: "read/write", doc: {"summary":"Returns or sets the description of the Japanese input rules. Can be one of the XlIMEMode constants listed in the following table. Read/write Long.","params":[],"source":"external"} },
		{ name: "InCellDropdown", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if data validation displays a drop-down list that contains acceptable values. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "InputMessage", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Returns or sets the data validation input message. Read/write String.","params":[],"source":"external"} },
		{ name: "InputTitle", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Returns or sets the title of the data-validation input dialog box. Read/write String. Limited to 32 characters.","params":[],"source":"external"} },
		{ name: "Modify", kind: "method", signature: "Modify([Type As Variant], [AlertStyle As Variant], [Operator As Variant], [Formula1 As Variant], [Formula2 As Variant])", doc: {"summary":"Modifies data validation for a range.","params":[{"name":"Type","text":"An XlDVType value that represents the validation type.","type":"Variant"},{"name":"AlertStyle","text":"An XlDVAlertStyle value that represents the validation alert style.","type":"Variant"},{"name":"Operator","text":"An XlFormatConditionOperator value that represents the data validation operator.","type":"Variant"},{"name":"Formula1","text":"The first part of the data validation equation.","type":"Variant"},{"name":"Formula2","text":"The second part of the data validation equation when Operator is xlBetween or xlNotBetween; otherwise, this argument is ignored.","type":"Variant"}],"source":"external"} },
		{ name: "Operator", kind: "property", declaredType: "Long", access: "read-only", doc: {"summary":"Returns a Long value that represents the operator for the data validation. See XlFormatConditionOperator.","params":[],"source":"external"} },
		{ name: "Parent", kind: "property", declaredType: "Object", access: "read-only", doc: {"summary":"Returns the parent object for the specified object. Read-only.","params":[],"source":"external"} },
		{ name: "ShowError", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if the data validation error message will be displayed whenever the user enters invalid data. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "ShowInput", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if the data validation input message will be displayed whenever the user selects a cell in the data validation range. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "Type", kind: "property", declaredType: "Long", access: "read-only", doc: {"summary":"Returns a Long value containing an XlDVType constant that represents the data type validation for a range.","params":[],"source":"external"} },
		{ name: "Value", kind: "property", declaredType: "Boolean", access: "read-only", doc: {"summary":"Returns a Boolean value that indicates if all the validation criteria are met (that is, if the range contains valid data).","params":[],"source":"external"} },
	],
