	"SeriesCollection": [
		{ name: "_Default", kind: "method", returns: "Excel.Series", hidden: true, signature: "_Default(Index As Variant) As Series" },
		{ name: "_NewEnum", kind: "method", hidden: true, signature: "_NewEnum() As IUnknown" },
		{ name: "Add", kind: "method", returns: "Excel.Series", signature: "Add(Source As Variant, [Rowcol As XlRowCol], [SeriesLabels As Variant], [CategoryLabels As Variant], [Replace As Variant]) As Series", doc: {"summary":"Adds one or more new series to the SeriesCollection collection.","params":[{"name":"Source","text":"The new data as a Range object.","type":"Variant"},{"name":"Rowcol","text":"Specifies whether the new values are in the rows or columns of the specified range.","type":"XlRowCol"},{"name":"SeriesLabels","text":"True if the first row or column contains the name of the data series. False if the first row or column contains the first data point of the series. If this argument is omitted, Microsoft Excel attempts to determine the location of the series name from the contents of the first row or column.","type":"Variant"},{"name":"CategoryLabels","text":"True if the first row or column contains the name of the category labels. False if the first row or column contains the first data point of the series. If this argument is omitted, Excel attempts to determine the location of the category label from the contents of the first row or column.","type":"Variant"},{"name":"Replace","text":"If _CategoryLabels_ is True and _Replace_ is True, the specified categories replace the categories that currently exist for the series. If _Replace_ is False, the existing categories will not be replaced. The default value is False.","type":"Variant"}],"source":"external"} },
		{ name: "Application", kind: "property", returns: "Excel.Application", declaredType: "Application", access: "read-only", doc: {"summary":"When used without an object qualifier, this property returns an Application object that represents the Microsoft Excel application.","params":[],"source":"external"} },
		{ name: "Count", kind: "property", declaredType: "Long", access: "read-only", doc: {"summary":"Returns a Long value that represents the number of objects in the collection.","params":[],"source":"external"} },
		{ name: "Creator", kind: "property", declaredType: "XlCreator", access: "read-only", doc: {"summary":"Returns a 32-bit integer that indicates the application in which this object was created. Read-only Long.","params":[],"source":"external"} },
		{ name: "Extend", kind: "method", signature: "Extend(Source As Variant, [Rowcol As Variant], [CategoryLabels As Variant]) As Variant", doc: {"summary":"Adds new data points to an existing series collection.","params":[{"name":"Source","text":"The new data to be added to the SeriesCollection object as a Range object.","type":"Variant"},{"name":"Rowcol","text":"Specifies whether the new values are in the rows or columns of the given range source. Can be one of the following XlRowCol constants: xlRows or xlColumns. If this argument is omitted, Microsoft Excel attempts to determine where the values are by the size and orientation of the selected range or by the dimensions of the array.","type":"Variant"},{"name":"CategoryLabels","text":"True to have the first row or column contain the name of the category labels. False to have the first row or column contain the first data point of the series. If this argument is omitted, Excel attempts to determine the location of the category label from the contents of the first row or column.","type":"Variant"}],"source":"external"} },
		{ name: "Item", kind: "method", returns: "Excel.Series", signature: "Item(Index As Variant) As Series", doc: {"summary":"Returns a single object from a collection.","params":[{"name":"Index","text":"The name or index number for the object.","type":"Variant"}],"source":"external"} },
		{ name: "NewSeries", kind: "method", returns: "Excel.Series", signature: "NewSeries() As Series", doc: {"summary":"Creates a new series. Returns a Series object that represents the new series.","params":[],"source":"external"} },
		{ name: "Parent", kind: "property", declaredType: "Object", access: "read-only", doc: {"summary":"Returns the parent object for the specified object. Read-only.","params":[],"source":"external"} },
		{ name: "Paste", kind: "method", signature: "Paste([Rowcol As XlRowCol], [SeriesLabels As Variant], [CategoryLabels As Variant], [Replace As Variant], [NewSeries As Variant]) As Variant", doc: {"summary":"Pastes data from the Clipboard into the specified series collection.","params":[{"name":"Rowcol","text":"Specifies whether the values corresponding to a particular data series are in rows or columns.","type":"XlRowCol"},{"name":"SeriesLabels","text":"True to use the contents of the cell in the first column of each row (or the first row of each column) as the name of the data series in that row (or column). False to use the contents of the cell in the first column of each row (or the first row of each column) as the first data point in the data series. The default value is False.","type":"Variant"},{"name":"CategoryLabels","text":"True to use the contents of the first row (or column) of the selection as the categories for the chart. False to use the contents of the first row (or column) as the first data series in the chart. The default value is False.","type":"Variant"},{"name":"Replace","text":"True to apply categories while replacing existing categories with information from the copied range. False to insert new categories without replacing any old ones. The default value is True.","type":"Variant"},{"name":"NewSeries","text":"True to paste the data as a new series. False to paste the data as new points in an existing series. The default value is True.","type":"Variant"}],"source":"external"} },
	],
