	"TextConnection": [
		{ name: "Application", kind: "property", returns: "Excel.Application", declaredType: "Application", access: "read-only", doc: {"summary":"Returns an Application object that represents the Microsoft Excel application. Read-only.","params":[],"source":"external"} },
		{ name: "Connection", kind: "property", declaredType: "Variant", access: "read/write", doc: {"summary":"Returns or sets a string that contains text file names that enable Microsoft Excel to connect to text data sources. Read/write Variant.","params":[],"source":"external"} },
		{ name: "Creator", kind: "property", declaredType: "XlCreator", access: "read-only", doc: {"summary":"Returns a 32-bit integer that indicates the application in which the specified object was created. Read-only Long.","params":[],"source":"external"} },
		{ name: "Parent", kind: "property", declaredType: "Object", access: "read-only", doc: {"summary":"Returns an Object that represents the parent object of the specified TextConnection object. Read-only.","params":[],"source":"external"} },
		{ name: "TextFileColumnDataTypes", kind: "property", declaredType: "Variant", access: "read/write", doc: {"summary":"Returns or sets an ordered array of constants that specify the data types applied to the corresponding columns in the text file that you are importing into a query table. The default constant for each column is xlGeneral. Read/write Variant.","params":[],"source":"external"} },
		{ name: "TextFileCommaDelimiter", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if the comma is the delimiter when you import a text file into a query table. False if you want to use some other character as the delimiter. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "TextFileConsecutiveDelimiter", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if consecutive delimiters are treated as a single delimiter when you import a text file into a query table. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "TextFileDecimalSeparator", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Returns or sets the decimal separator character that Microsoft Excel uses when you import a text file into a query table. The default is the system decimal separator character. Read/write String.","params":[],"source":"external"} },
		{ name: "TextFileFixedColumnWidths", kind: "property", declaredType: "Variant", access: "read/write", doc: {"summary":"Returns or sets an array of integers that correspond to the widths of the columns (in characters) in the text file that you are importing into a query table. Valid widths are from 1 through 32767 characters. Read/write Variant.","params":[],"source":"external"} },
		{ name: "TextFileHeaderRow", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Returns or sets a value that specifies whether the first row (from the starting row) should be treated as a header row. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "TextFileOtherDelimiter", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Returns or sets the character used as the delimiter when you import a text file into a query table. The default value is null. Read/write String.","params":[],"source":"external"} },
		{ name: "TextFileParseType", kind: "property", declaredType: "XlTextParsingType", access: "read/write", doc: {"summary":"Returns or sets the column format for the data in the text file that you are importing into a query table. Read/write XlTextParsingType enumeration.","params":[],"source":"external"} },
		{ name: "TextFilePlatform", kind: "property", declaredType: "XlPlatform", access: "read/write", doc: {"summary":"Returns or sets the origin of the text file that you are importing into the query table. This property determines which code page is used during the data import. Read/write XlPlatform.","params":[],"source":"external"} },
		{ name: "TextFilePromptOnRefresh", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if you want to specify the name of the imported text file each time the query table is refreshed. The Import Text File dialog box allows you to specify the path and file name. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "TextFileSemicolonDelimiter", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if the semicolon is the delimiter when you import a text file into a query table, and if the value of the TextFileParseType property is xlDelimited. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "TextFileSpaceDelimiter", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if the space character is the delimiter when you import a text file into a query table. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "TextFileStartRow", kind: "property", declaredType: "Long", access: "read/write", doc: {"summary":"Returns or sets the row number at which text parsing will begin when you import a text file into a query table. Valid values are integers from 1 through 32767. The default value is 1. Read/write Long.","params":[],"source":"external"} },
		{ name: "TextFileTabDelimiter", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if the tab character is the delimiter when you import a text file into a query table. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "TextFileTextQualifier", kind: "property", declaredType: "XlTextQualifier", access: "read/write", doc: {"summary":"Returns or sets the text qualifier when you import a text file into a query table. The text qualifier specifies that the enclosed data is in text format. Read/write XlTextQualifier.","params":[],"source":"external"} },
		{ name: "TextFileThousandsSeparator", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Returns or sets the thousands separator character that Microsoft Excel uses when you import a text file into a query table. The default is the system thousands separator character. Read/write String.","params":[],"source":"external"} },
		{ name: "TextFileTrailingMinusNumbers", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True for Microsoft Excel to treat numbers imported as text that begin with a - (minus) symbol as a negative symbol. False for Excel to treat numbers imported as text that begin with a - symbol as text. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "TextFileVisualLayout", kind: "property", declaredType: "XlTextVisualLayoutType", access: "read/write", doc: {"summary":"Returns or sets an XlTextVisualLayoutType value that indicates whether the visual layout of the text being imported is left-to-right or right-to-left. Read/write.","params":[],"source":"external"} },
	],
