	"WebOptions": [
		{ name: "AllowPNG", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if Portable Network Graphics (PNG) is allowed as an image format when you save documents as a webpage. False if PNG is not allowed as an output format. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "Application", kind: "property", returns: "Excel.Application", declaredType: "Application", access: "read-only", doc: {"summary":"When used without an object qualifier, this property returns an Application object that represents the Microsoft Excel application.","params":[],"source":"external"} },
		{ name: "Creator", kind: "property", declaredType: "XlCreator", access: "read-only", doc: {"summary":"Returns a 32-bit integer that indicates the application in which this object was created. Read-only Long.","params":[],"source":"external"} },
		{ name: "DownloadComponents", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if the necessary Microsoft Office Web components are downloaded when you view the saved document in a web browser, but only if the components are not already installed. False if the components are not downloaded. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "Encoding", kind: "property", declaredType: "MsoEncoding", access: "read/write", doc: {"summary":"Returns or sets the document encoding (code page or character set) to be used by the web browser when you view the saved document. The default is the system code page. Read/write MsoEncoding.","params":[],"source":"external"} },
		{ name: "FolderSuffix", kind: "property", declaredType: "String", access: "read-only", doc: {"summary":"Returns the folder suffix that Microsoft Excel uses when you save a document as a webpage, use long file names, and choose to save supporting files in a separate folder (that is, if the UseLongFileNames and OrganizeInFolder properties are set to True). Read-only String.","params":[],"source":"external"} },
		{ name: "LocationOfComponents", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Returns or sets the central URL (on the intranet or web) or path (local or network) to the location from which authorized users can download Microsoft Office Web components when viewing your saved document. The default value is the local or network installation path for Microsoft Office. Read/write String.","params":[],"source":"external"} },
		{ name: "OrganizeInFolder", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if all supporting files, such as background textures and graphics, are organized in a separate folder when you save the specified document as a webpage. False if supporting files are saved in the same folder as the webpage. The default value is True. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "Parent", kind: "property", declaredType: "Object", access: "read-only", doc: {"summary":"Returns the parent object for the specified object. Read-only.","params":[],"source":"external"} },
		{ name: "PixelsPerInch", kind: "property", declaredType: "Long", access: "read/write", doc: {"summary":"Returns or sets the density (pixels per inch) of graphics images and table cells on a webpage. The range of settings is usually from 19 to 480, and common settings for popular screen sizes are 72, 96, and 120. The default setting is 96. Read/write Long.","params":[],"source":"external"} },
		{ name: "RelyOnCSS", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if cascading style sheets (CSS) are used for font formatting when you view a saved document in a web browser. Microsoft Excel creates a cascading style sheet file and saves it either to the specified folder or to the same folder as your webpage, depending on the value of the OrganizeInFolder property. False if HTML <FONT> tags and cascading style sheets are used. The default value is True. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "RelyOnVML", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if image files are not generated from drawing objects when you save a document as a webpage. False if images are generated. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "ScreenSize", kind: "property", declaredType: "MsoScreenSize", access: "read/write", doc: {"summary":"Returns or sets the ideal minimum screen size (width by height, in pixels) that you should use when viewing the saved document in a web browser. Can be one of the MsoScreenSize constants. The default constant is msoScreenSize800x600. Read/write MsoScreenSize.","params":[],"source":"external"} },
		{ name: "TargetBrowser", kind: "property", declaredType: "MsoTargetBrowser", access: "read/write", doc: {"summary":"Returns or sets an MsoTargetBrowser constant indicating the browser version. Read/write.","params":[],"source":"external"} },
		{ name: "UseDefaultFolderSuffix", kind: "method", signature: "UseDefaultFolderSuffix()", doc: {"summary":"Sets the folder suffix for the specified document to the default suffix for the language support that you have selected or installed.","params":[],"source":"external"} },
		{ name: "UseLongFileNames", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if long file names are used when you save the document as a webpage. False if long file names are not used and the DOS file name format (8.3) is used. The default value is True. Read/write Boolean.","params":[],"source":"external"} },
	],
