	"Speech": [
		{ name: "Direction", kind: "property", declaredType: "XlSpeakDirection", access: "read/write", doc: {"summary":"Returns or sets the order in which the cells will be spoken. The value of the Direction property is an XlSpeakDirection constant. Read/write.","params":[],"source":"external"} },
		{ name: "Speak", kind: "method", signature: "Speak(Text As String, [SpeakAsync As Variant], [SpeakXML As Variant], [Purge As Variant])", doc: {"summary":"Microsoft Excel plays back the text string that is passed as an argument.","params":[{"name":"Text","text":"The text to be spoken.","type":"String"},{"name":"SpeakAsync","text":"True causes the text to be spoken asynchronously (the method will not wait for the text to be spoken). False causes the text to be spoken synchronously (the method waits for the text to be spoken before continuing). The default is False.","type":"Variant"},{"name":"SpeakXML","text":"True causes the text to be interpreted as XML. False causes the text to not be interpreted as XML, so any XML tags are read and not interpreted. The default is False.","type":"Variant"},{"name":"Purge","text":"True causes current speech to be terminated and any buffered text to be purged before text is spoken. False does not cause the current speech to be terminated and does not purge the buffered text before text is spoken. The default is False.","type":"Variant"}],"source":"external"} },
		{ name: "SpeakCellOnEnter", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Microsoft Excel supports a mode where the active cell is spoken when the Enter key is pressed or when the active cell is finished being edited. Setting the SpeakCellOnEnter property to True turns this mode on. False turns this mode off. Read/write Boolean.","params":[],"source":"external"} },
	],
	"SpellingOptions": [
		{ name: "ArabicModes", kind: "property", declaredType: "XlArabicModes", access: "read/write", doc: {"summary":"Returns or sets the mode for the Arabic spelling checker. Read/write XlArabicModes.","params":[],"source":"external"} },
		{ name: "ArabicStrictAlefHamza", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Returns or sets whether the spelling checker uses rules regarding Arabic words beginning with an alef hamza. Read/write.","params":[],"source":"external"} },
		{ name: "ArabicStrictFinalYaa", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Returns or sets whether the spelling checker uses rules regarding Arabic words ending with the letter yaa. Read/write.","params":[],"source":"external"} },
		{ name: "ArabicStrictTaaMarboota", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Returns or sets whether the spelling checker uses rules to flag Arabic words ending with haa instead of taa marboota. Read/write.","params":[],"source":"external"} },
		{ name: "BrazilReform", kind: "property", declaredType: "XlPortugueseReform", access: "read/write", doc: {"summary":"Returns or sets the mode for checking the spelling of Brazilian Portuguese. Read/write.","params":[],"source":"external"} },
		{ name: "DictLang", kind: "property", declaredType: "Long", access: "read/write", doc: {"summary":"Selects the dictionary language used when Microsoft Excel performs spelling checks. Read/write Long.","params":[],"source":"external"} },
		{ name: "GermanPostReform", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True to check the spelling of words by using the German post-reform rules. False cancels this feature. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "HebrewModes", kind: "property", declaredType: "XlHebrewModes", access: "read/write", doc: {"summary":"Returns or sets the mode for the Hebrew spelling checker. Read/write XlHebrewModes.","params":[],"source":"external"} },
		{ name: "IgnoreCaps", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"False instructs Microsoft Excel to check for uppercase words; True instructs Excel to ignore words in uppercase when using the spelling checker. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "IgnoreFileNames", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"False instructs Microsoft Excel to check for Internet and file addresses; True instructs Excel to ignore Internet and file addresses when using the spell checker. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "IgnoreMixedDigits", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"False instructs Microsoft Excel to check for mixed digits; True instructs Excel to ignore mixed digits when checking spelling. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "KoreanCombineAux", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"When set to True, Microsoft Excel combines Korean auxiliary verbs and adjectives when spelling is checked. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "KoreanProcessCompound", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"When set to True, this enables Microsoft Excel to process Korean compound nouns when using the spelling checker. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "KoreanUseAutoChangeList", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"When set to True, this enables Microsoft Excel to use the auto-change list for Korean words when using the spelling checker. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "PortugalReform", kind: "property", declaredType: "XlPortugueseReform", access: "read/write", doc: {"summary":"Returns or sets the mode for checking the spelling of European Portuguese. Read/write.","params":[],"source":"external"} },
		{ name: "RussianStrictE", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Returns or sets whether the spelling checker uses rules regarding Russian words containing the character . Read/write.","params":[],"source":"external"} },
		{ name: "SpanishModes", kind: "property", declaredType: "XlSpanishModes", access: "read/write", doc: {"summary":"Returns or sets the mode for checking the spelling of Spanish. Read/write.","params":[],"source":"external"} },
		{ name: "SuggestMainOnly", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"When set to True, instructs Microsoft Excel to suggest words from only the main dictionary when using the spelling checker. False removes the limits of suggesting words from only the main dictionary when using the spelling checker. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "UserDict", kind: "property", declaredType: "String", access: "read/write", doc: {"summary":"Instructs Microsoft Excel to create a custom dictionary to which new words can be added when performing spelling checks on a worksheet. Read/write String.","params":[],"source":"external"} },
	],
