	"TableObject": [
		{ name: "AdjustColumnWidth", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Specifies if the column widths are automatically adjusted for the best fit each time you refresh the specified query table. The default value is True. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "Application", kind: "property", returns: "Excel.Application", declaredType: "Application", access: "read-only", doc: {"summary":"Returns an Application object that represents the Microsoft Excel application. Read-only.","params":[],"source":"external"} },
		{ name: "Creator", kind: "property", declaredType: "XlCreator", access: "read-only", doc: {"summary":"Returns a 32-bit integer that indicates the application in which the specified object was created. Read-only Long.","params":[],"source":"external"} },
		{ name: "Delete", kind: "method", signature: "Delete()", doc: {"summary":"Deletes the TableObject object.","params":[],"source":"external"} },
		{ name: "Destination", kind: "property", returns: "Excel.Range", declaredType: "Range", access: "read-only", doc: {"summary":"Returns the cell in the upper-left corner of the query table destination range (the range where the resulting query table will be placed). The destination range must be on the worksheet that contains the TableObject object. Read-only Range.","params":[],"source":"external"} },
		{ name: "EnableEditing", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if the user can edit the specified query table. False if the user can only refresh the query table. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "EnableRefresh", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Specifies if the query table can be refreshed by the user. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "FetchedRowOverflow", kind: "property", declaredType: "Boolean", access: "read-only", doc: {"summary":"Specifies if the number of rows returned by the last use of the Refresh method is greater than the number of rows available on the worksheet. Read-only Boolean.","params":[],"source":"external"} },
		{ name: "ListObject", kind: "property", returns: "Excel.ListObject", declaredType: "ListObject", access: "read-only", doc: {"summary":"Returns a ListObject object for the TableObject object. Read-only.","params":[],"source":"external"} },
		{ name: "Parent", kind: "property", declaredType: "Object", access: "read-only", doc: {"summary":"Returns an Object that represents the parent object of the specified TableObject object. Read-only.","params":[],"source":"external"} },
		{ name: "PreserveColumnInfo", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Specifies if column sorting, filtering, and layout information is preserved whenever a query table is refreshed. The default value is False. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "PreserveFormatting", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"True if any formatting common to the first five rows of data are applied to new rows of data in the query table. Unused cells aren't formatted. The property is False if the last AutoFormat applied to the query table is applied to new rows of data. The default value is True. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "Refresh", kind: "method", signature: "Refresh() As Boolean", doc: {"summary":"This method updates the TableObject object.","params":[],"source":"external"} },
		{ name: "RefreshStyle", kind: "property", declaredType: "XlCellInsertionMode", access: "read/write", doc: {"summary":"Returns or sets the way rows on the specified worksheet are added or deleted to accommodate the number of rows in a record set returned by a query. Read/write XlCellInsertionMode enumeration.","params":[],"source":"external"} },
		{ name: "ResultRange", kind: "property", returns: "Excel.Range", declaredType: "Range", access: "read-only", doc: {"summary":"Returns a Range object that represents the area of the worksheet occupied by the specified query table. Read-only.","params":[],"source":"external"} },
		{ name: "RowNumbers", kind: "property", declaredType: "Boolean", access: "read/write", doc: {"summary":"Specifies if row numbers are added as the first column of the specified query table. Read/write Boolean.","params":[],"source":"external"} },
		{ name: "WorkbookConnection", kind: "property", returns: "Excel.WorkbookConnection", declaredType: "WorkbookConnection", access: "read-only", doc: {"summary":"Returns the WorkbookConnection object used by the TableObject for connecting to the model.","params":[],"source":"external"} },
	],
